SELECT 
FROM `notification` n

WHERE n.user_id = #{userId}
  AND n.notice_type = #{noticeType}
  AND n.ref_type = #{refType}
  AND n.ref_id = #{refId}
  AND n.status = 1
ORDER BY n.id DESC
LIMIT 1

SELECT 
FROM `notification` n


    n.status = 1

        AND n.user_id = #{userId}


        AND n.title LIKE CONCAT('%', #{title}, '%')


        AND n.notice_type = #{noticeType}


        AND n.level = #{level}


        AND n.is_read = #{isRead}


        AND n.ref_type = #{refType}


        AND n.send_time >= #{startTime}


        AND n.send_time <= #{endTime}


ORDER BY n.id DESC

mapper.update:
UPDATE `notification` n
SET n.is_read = 1, n.read_time = #{readTime}
WHERE n.id = #{id} AND n.user_id = #{userId}
  AND n.notice_type = 1 AND n.status = 1 AND n.is_read = 0
  AND COALESCE(n.ref_type, 'system_announcement') = 'system_announcement'

mapper.select:
SELECT COUNT(1) AS totalCount, COALESCE(SUM(CASE WHEN is_read = 0 THEN 1 ELSE 0 END), 0) AS unreadCount, COALESCE(SUM(CASE WHEN is_read = 1 THEN 1 ELSE 0 END), 0) AS readCount, COALESCE(SUM(CASE WHEN level = 3 THEN 1 ELSE 0 END), 0) AS urgentCount, COALESCE(SUM(CASE WHEN notice_type = 2 THEN 1 ELSE 0 END), 0) AS taskNoticeCount FROM `notification`
status = 1
AND user_id = #{userId}

SELECT MIN(n.id) AS id, NULL AS user_id, NULL AS username, NULL AS nickname, MAX(n.title) AS title, MAX(n.content) AS content, 2 AS notice_type, MAX(n.ref_type) AS ref_type, COALESCE(n.ref_id, n.id) AS ref_id, MAX(COALESCE(n.task_id, CASE WHEN n.ref_type = 'farm_task' THEN n.ref_id ELSE NULL END)) AS task_id, MAX(ft.task_title) AS task_title, MAX(ft.task_type) AS task_type, MAX(ft.status) AS task_status, MAX(p.plot_name) AS plot_name, MAX(n.alert_id) AS alert_id, NULL AS alert_title, NULL AS alert_level, MAX(n.level) AS level, NULL AS is_read, NULL AS read_time, MAX(n.send_time) AS send_time, MAX(n.publisher_id) AS publisher_id, MAX(n.publisher_name) AS publisher_name, COUNT(1) AS recipient_count, COALESCE(SUM(CASE WHEN n.is_read = 1 THEN 1 ELSE 0 END), 0) AS read_count, 1 AS status, MAX(n.remark) AS remark, MIN(n.create_time) AS create_time, MAX(n.update_time) AS update_time FROM `notification` n LEFT JOIN `farm_task` ft ON ft.id = COALESCE(n.task_id, CASE WHEN n.ref_type = 'farm_task' THEN n.ref_id ELSE NULL END) LEFT JOIN `plot` p ON p.id = ft.plot_id
n.status = 1 AND n.notice_type = 2 AND COALESCE(n.ref_type, 'farm_task_message') IN ('farm_task_message', 'farm_task')
AND n.user_id = #{userId}
AND n.title LIKE CONCAT('%', #{title}, '%')
AND n.content LIKE CONCAT('%', #{content}, '%')
AND p.plot_name LIKE CONCAT('%', #{plotName}, '%')
AND n.send_time >= #{startTime}
AND n.send_time <= #{endTime}
GROUP BY COALESCE(n.ref_id, n.id) ORDER BY MAX(n.send_time) DESC, MIN(n.id) DESC

SELECT COUNT(1) AS totalCount, COALESCE(SUM(CASE WHEN grouped.send_time >= CURDATE() THEN 1 ELSE 0 END), 0) AS todayCount, COALESCE(SUM(grouped.recipient_count - grouped.read_count), 0) AS unreadDeliveryCount, COALESCE(SUM(grouped.read_count), 0) AS readDeliveryCount FROM ( SELECT COALESCE(n.ref_id, n.id) AS message_group_id, MAX(n.send_time) AS send_time, COUNT(1) AS recipient_count, COALESCE(SUM(CASE WHEN n.is_read = 1 THEN 1 ELSE 0 END), 0) AS read_count FROM `notification` n WHERE n.status = 1 AND n.notice_type = 2 AND COALESCE(n.ref_type, 'farm_task_message') IN ('farm_task_message', 'farm_task')
AND n.user_id = #{userId}
GROUP BY COALESCE(n.ref_id, n.id) ) grouped

mapper.update:
UPDATE `notification`
SET is_read = #{isRead},
    read_time = #{readTime}
WHERE id = #{id}

UPDATE `notification`
SET is_read = 1,
    read_time = #{readTime}

    status = 1
    AND is_read = 0

        AND user_id = #{userId}
